// Sequential runner: contracted stages, logged handoffs, replayable (plain JS)
async function runSequential(stages, runStage, initial) {
  const log = [];
  let carry = initial;
  for (const stage of stages) {
    const gate = handoff(stage.needs, carry); // Ch.3 mechanical gate
    if (!gate.ok) return { ok: false, failedAt: stage.name, error: gate.error, log };
    carry = await runStage(stage, gate.input);
    log.push([stage.name, carry]);
  }
  return { ok: true, result: carry, log };
}
// Failure names its stage with the log proving every prior handoff.

