// Sync twin (same gating logic, no awaits — playground-safe)
function runSequential(stages, runStage, initial) {
  const log = [];
  let carry = initial;
  for (const stage of stages) {
    const need = stage.needs || [];
    const missing = need.filter((k) => !(k in carry));
    if (missing.length) return { ok: false, failedAt: stage.name, log };
    const input = {};
    for (const k of need) input[k] = carry[k];
    Object.assign(carry, runStage(stage, input));
    log.push(stage.name);
  }
  return { ok: true, result: carry, log };
}
const stages = [
  { name: 'research', needs: [] },
  { name: 'write', needs: ['facts'] },
  { name: 'review', needs: ['draft'] },
];
function fakeStage(stage, input) {
  if (stage.name === 'research') return { facts: '30-day window' };
  if (stage.name === 'write') return { draft: 'Draft re ' + input.facts };
  return { verdict: 'pass' };
}
const r = runSequential(stages, fakeStage, {});
console.log('ok=' + r.ok);
console.log('stages=' + r.log.join(','));
console.log('draft=' + r.result.draft);

